package android.content; import android.net.Uri; import java.util.*;
public class Intent { private String action; private Uri data; private Class<?> component; private String pkg; private final Map<String,Object> extras=new HashMap<>(); public Intent(){} public Intent(String action){this.action=action;} public Intent(Context c,Class<?> component){this.component=component;} public Intent setAction(String v){action=v;return this;} public String getAction(){return action;} public Intent setData(Uri v){data=v;return this;} public Uri getData(){return data;} public Class<?> getComponentClass(){return component;} public Intent setPackage(String p){pkg=p;return this;} public String getPackage(){return pkg;} public Intent putExtra(String k,long v){extras.put(k,v);return this;} public Intent putExtra(String k,String v){extras.put(k,v);return this;} public long getLongExtra(String k,long d){Object v=extras.get(k);return v instanceof Number?((Number)v).longValue():d;} public String getStringExtra(String k){Object v=extras.get(k);return v==null?null:String.valueOf(v);} public Map<String,Object> extras(){return extras;} public Intent copy(){Intent x=new Intent();x.action=action;x.data=data;x.component=component;x.pkg=pkg;x.extras.putAll(extras);return x;} }
